WITH payload AS (SELECT $archive_payload$[{"id":"486fae2e-5217-5a5c-922f-505c0dc9fc9e","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -سب وشتم موظفة أثناء تأديتها عملها -تهديد -إقرار بالتنازل عن احلق اخلاص -التعزير باجللد وأخذ التعهد.","document_number":"34222635","case_number":"34186693","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/23","year":"1434","subject":"اعتداء -سب وشتم موظفة أثناء تأديتها عملها -تهديد -إقرار بالتنازل عن احلق اخلاص -التعزير باجللد وأخذ التعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34222635:‬تاريخه‪1434/04/23 :‬هـ‬\n                          ‫رقم الدعوى‪34186693:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 34264827:‬تاريخه‪1434/07/10:‬هـ‬\n\n\n       ‫اعتــداء ‪ -‬ســب وشــتم موظفــة أثنــاء تأديتهــا عملهــا ‪ -‬تهديــد ‪ -‬إقــرار‬\n             ‫بالتنــازل عــن احلــق اخلــاص ‪ -‬التعزيــر باجللــد وأخــذ التعهــد‪.‬‬\n\n\n\n\n          ‫‪ -‬قوله عليه الصالة والسالم‪( :‬سباب املسلم فسوق وقتاله كفر )‪.‬‬\n       ‫‪ -‬قولــه صلــى اهلل عليــه وســلم قــال‪( :‬كل املســلم علــى املســلم حــرام‬\n                                            ‫دمــه ومالــه وعرضــه ) رواه مســلم‪.‬‬\n\n\n\n\n       ‫انتهــى التحقيــق إلــى اتهــام املدعــى عليــه األول بالســب والشــتم إلحــدى‬\n       ‫العامــات يف أحــد املســتوصفات أثنــاء تأديتهــا عملهــا وتهديــده لهــا ‪،‬‬\n       ‫واتهــام املدعــى عليهــا الثانيــة بالتلفــظ بألفــاظ غيــر الئقــة علــى إحــدى‬\n       ‫العامــات باملســتوصف أثنــاء تأديتهــا عملهــا ‪ ،‬طلــب املدعــي العام إثبات‬\n       ‫إدانتهمــا مبــا أســند إليهمــا واحلكــم عليهمــا بعقوبــة تعزيريــة ‪ ،‬حضــرت‬\n       ‫املدعيــة باحلــق اخلــاص وادعــت علــى املدعــى عليهمــا مبثــل مــا ادعــى بــه‬\n       ‫املدعــي العــام وطلبــت تعزيرهمــا ‪ ،‬بعــرض دعــوى املدعــي العــام واملدعية‬\n       ‫باحلــق اخلــاص علــى املدعــى عليــه األول صــادق عليهــا جملــة وتفصيــا‪،‬‬\n       ‫ودفــع أنــه كان يف حالــة غضــب شــديد وقــرر توبتــه وندمــه واعتــذاره‪،‬‬\n       ‫وبعــرض الدعــوى علــى املدعــى عليهــا أجابــت أن الصحيــح أنهــا تلفظــت‬\n\n‫‪159‬‬\n\f‫علــى املدعــى عليهــا وقــررت أنهــا اعتــذرت مــن املدعيــة وأنهــا ســامحتها‬\n‫علــى ذلــك ‪ ،‬قــررت املدعيــة باحلــق اخلــاص أنهــا ســامحت املدعــى عليهــا‬\n‫يف املســتوصف حــن اعتــذرت منهــا وخرجــت ثــم عــاد زوجهــا بعــد ذلــك‪.‬‬\n‫وتلفــظ عليهــا ‪ ،‬نظــر ًا إلقــرار املدعــى عليــه األول بدعــوى املدعــى العــام‬\n‫ا ويف هــذا إدانــه لــه مبــا يدعيانــه‪،‬‬‫واملدعيــة باحلــق اخلــاص جملــة وتفصيـ ً‬\n‫وإلقــرار املدعــى عليهــا الثانيــة ببعــض مــا جــاء يف دعــوى املدعــى العــام‬\n‫واملدعيــة باحلــق اخلــاص وإقــرار املدعيــة باحلــق اخلــاص بتنازلهــا عــن‬\n‫املدعــى عليهــا الثانيــة لــذا مت احلكــم بــرد دعــوى املدعيــة باحلــق اخلــاص‬\n‫طلبهــا تأديــب املدعــى عليهــا الثانيــة لقــاء مــا تلفظــت بــه عليهــا وذلــك‬\n‫إلقرارهــا بتنازلهــا عنهــا كمــا ثبتــت إدانــة املدعــى عليــه األول بتلفظــه‬\n‫علــى املدعيــة باحلــق اخلــاص وكان ذلــك أثنــاء تأديتهــا عملهــا ومت‬\n‫احلكــم بتعزيــره علــى ذلــك بجلــده ثمــان جلــدات مقســمة علــى النصــف‬\n‫للحــق العــام واحلــق اخلــاص يبــدأ أوال باحلــق العــام وبأخــذ التعهــد عليــه‬\n‫بعــدم العــودة ملثــل مــا بــدر منــه‪ ،‬كمــا ثبتــت إدانــة املدعــى عليهــا الثانيــة‬\n‫بالتلفــظ علــى املدعــى عليهــا باحلــق اخلــاص ومت احلكم للحــق العام بأخذ‬\n‫التعهــد عليهــا بعــدم العــودة ملثــل مــا بــدر منهــا ‪ ،‬بعــرض احلكــم علــى‬\n‫األطــراف قــرر املدعــي العــام عــدم القناعــة باحلكــم مكتفي ـ ًا بالئحــة‬\n‫الدعــوى املقدمــة معتبــر ًا إياهــا الئحــة اعتراضيــة واملدعــى عليهــا باحلــق‬\n‫اخلــاص قــررت عــدم القناعــة باحلكــم ورفعهــا بالئحــة اعتراضيــة كمــا‬\n‫قــرر املدعــى عليهمــا كل واحــد منهمــا مبفــرده قناعتــه باحلكــم‪ ،‬وبعــد‬\n                   ‫رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n                                                                                           ‫‪160‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي املنتــدب املكلــف باملكتــب‬\n      ‫(‪ )5‬يف احملكمــة العامــة بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة بعنيــزة برقــم ‪ 34186693‬وتاريــخ‬\n      ‫‪1434/04/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34992714‬وتاريــخ‬\n      ‫‪1434/04/22‬ه ـ ففــي يــوم األحــد املوافق‪1434/05/19‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر املدعــي العــام ‪...‬وقــرر قائــا‬\n      ‫بصفتــي عضــو ًا بدائــرة التحقيــق واالدعــاء العــام مبحافظــة عنيــزة‬\n      ‫أدعــي علــى ‪ ... -1‬البالــغ مــن العمــر (‪ )31‬عام ـ ًا ســعودي اجلنســية‬\n      ‫مبوجــب الهويــة الوطنيــة رقــم (‪ )...‬متــزوج متعلــم موظــف حكومــي يقيــم‬\n      ‫مبحافظــة عنيــزة لــم يتــم إيقافــه‪... -2 .‬البالغــة مــن العمــر (‪ )35‬عامــا‬\n      ‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )...‬متزوجــة متعلمــة ربــة‬\n      ‫منــزل تقيــم مبحفظــة عنيــزة لــم يتــم إيقافهــا حيــث إنــه باالطــاع علــى‬\n      ‫خطــاب مديــر مركــز صحــي د‪.../‬مبحافظــة عنيــزة رقــم (‪ )752‬وتاريــخ‬\n      ‫‪1433/11/28‬ه ـ والــذي جــاء فيــه بــأن موظفــة الســجالت الطبيــة لــدى‬\n      ‫املركــز الصحــي ‪...‬ســجل مدنــي رقــم (‪ )...‬قــد تعرضــت للتهجــم بالســب‬\n      ‫والشــتم مــن قبــل املتهــم األول وزوجتــه املتهمــة الثانيــة وتطلــب أخــذ حقهــا‬\n      ‫وحــق والديهــا الشــرعي‪ .‬وبضبــط إفــادة املدعية ‪ ...‬ســجل مدنــي رقم (‪)...‬‬\n      ‫أفــادت أنهــا أثنــاء تأديــة عملهــا يف مســتوصف د‪... /‬تعرضــت للســب مــن‬\n      ‫إحــدى املراجعــات (املتهمــة الثانيــة) قائلة لها‪(:‬انقلعــي واطلعي‪،‬أبفصلك‬\n      ‫‪،‬وفصلتــك علــى يــدي‪ )..‬وكذلــك تعرضــت للســب مــن زوج الثانية(املتهم‬\n      ‫األول) قائ ًــا لهــا اهلل يلعــن اللــي ربــاك‪ )..‬وباالطــاع علــى احملضــر املعــد‬\n\n‫‪161‬‬\n\f‫مــن قبــل مديــر املســتوصف املواطــن ‪...‬هويــة وطنيــة رقــم (‪ )...‬ورد فيــه‬\n‫بأنــه قابــل املتهــم األول وطلــب منــه تقــدمي االعتــذار علــى مــا بــدر منــه‬\n‫إال أنــه رفــض ذلــك بشــدة وهــدد بأنــه لــو يســتطيع العتــدى علــى املدعيــة‬\n‫بيــده مهمــا كلفــه األمــر وبضبــط شــهادته أفــاد بأنــه ســمع املتهــم األول‬\n‫يقــول للمدعيــة ‪ « :‬اهلل يلعــن اللــي ربــاك «‪ .‬وباالطــاع علــى احملضــر‬\n‫املعــد مــن قبــل املدعيــة واملذيــل بتوقيــع كل مــن ‪...‬و‪...‬العامــات يف‬\n‫املســتوصف جــاء فيــه أن املتهمــة الثانيــة تلفظــت بألفــاظ غيــر الئقــة‬\n‫كقولهــا( انقلعــي‪ ،‬وأطلعــي بــرا ‪ ،‬أبفصلــك ‪ ،‬وفصلتــك علــى يــدي‪)..‬‬\n‫ودون إقــراره بذلــك ‪.‬وباســتجواب املتهــم األول أقــر بواقعــة الضبــط وبأنــه‬\n‫أثنــاء تواجــده داخــل املســتوصف قــام مبنــاداة املدعيــة كــي يتفاهــم معها‬\n‫حيــث أنهــا رفضــت أن تعطــي زوجتــه امللــف اخلــاص بهــا منكــر ًا تلفظــه‬\n‫عليهــا‪ .‬وباســتجواب املتهمــة الثانيــة أقــرت بواقعــة الضبــط وبأنــه حصــل‬\n‫بينهــا وبــن املدعيــة خــاف حــول تســليمها امللــف الطبــي فقــط منكــرة‬\n‫تلفظهــا عليهــا ودون إقرارهــا بذلــك‪ .‬وبالبحــث عــن ســوابقهما لــم يعثــر‬\n‫لهمــا علــى أي ســوابق جنائيــة مســجلة عليهمــا‪ .‬وملــا أشــير إليــه أقــرر‬\n‫اتهــام ‪ .........‬بالســب والشــتم إلحــدى العامــات باملســتوصف أثنــاء‬\n‫تأديتهــا عملهــا وتهديــده لهــا‪ .‬كمــا أقــرر اتهــام ‪...‬بالتلفــظ بألفــاظ غيــر‬\n‫الئقــة علــى إحــدى العامــات‪ .‬باملســتوصف أثنــاء تأديتهــا عملهــا وذلــك‬\n‫لألدلــة والقرائــن التاليــة ‪ -1‬مــا جــاء بشــهادة الشــاهد مديــر املســتوصف‬\n‫املنــوه عنهــا املدونــة علــى الصفحــة رقــم (‪ )6‬مــن دفتــر محاضــر التحقيــق‬\n‫املرفــق لفــة رقــم (‪-2 )19‬ماجــاء بشــهادة العامــات يف املســتوصف‬\n‫‪-‬املنــوه عنــه‪ -‬املــدون علــى الصفحــة رقــم (‪ -3 .)2‬مــا ورد بخطــاب مديــر‬\n‫املركــز الصحــي املرفــق لفــة رقــم(‪ -4 )4‬مــا ورد باســتدعاء املدعيــة‬\n\n\n                                                                                      ‫‪162‬‬\n\f      ‫املذيــل بشــهادة مديــر املســتوصف املرفــق لفــة (‪)2‬وحيــث إن مــا أقــدم‬\n      ‫عليــه املتهمــان املذكــوران فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب‬\n      ‫إحالتهــا للمحكمــة العامــة بعنيــزة إلثبــات إدانتهمــا مبــا أســند إليهمــا‬\n      ‫واحلكــم عليهمــا بعقوبــة تعزيريــة تزجرهمــا وتــردع غيرهمــا‪ .‬علم ـ ًا أن‬\n      ‫احلــق اخلــاص مــازال قائم ـ ًا وبــاهلل التوفيــق هكــذا ادعــى املدعــي العــام‬\n      ‫كمــا حضــرت املدعيــة باحلــق اخلــاص ‪...‬ســعودية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ...‬واملعــرف بهــا مــن قبــل والدهــا ‪...‬وادعــت مبــا ادعــى بــه املدعــي‬\n      ‫العــام حيــث قــررت قائلــه إن املدعــى عليــه ‪ ...‬قــام بالتلفــظ علــي بقولــه‬\n      ‫(‪ )......‬كمــا أن املدعــى عليهــا ‪ ...‬قامــت أيضــا بالتلفــظ علــي بقولهــا‬\n      ‫(انقلعــي واطلعــي بــرا وفصلتــك علــى يــدي) وأطلــب تعزيرهمــا علــى‬\n      ‫هــذه األلفــاظ هــذه دعــواي وبعــرض دعــوى املدعــي العــام واملدعيــة‬\n      ‫باحلــق اخلــاص علــى املدعــى عليــه األول أجــاب قائــا مــا ذكــره املدعــي‬\n      ‫العــام واملدعيــة باحلــق اخلــاص يف دعواهمــا ضــدي فكلــه صحيــح جملــة‬\n      ‫وتفصيــا فقــد تلفظــت بهــذه الكلمــة حيــث كنــت يف حالــة غضــب‬\n      ‫شــديد حيــث خرجــت زوجتــي تبكــي أمــام أطفالــي فغضبــت غضب ـ ًا‬\n      ‫شــديد ًا وقمــت بالتلفــظ عليهــا وأنــا اآلن نــادم علــى مــا بــدر منــي وأعتــذر‬\n      ‫عــن ذلــك أشــد االعتــذار هــذه إجابتــي كمــا أجابــت املدعــى عليهــا‬\n      ‫‪ ......‬بقولهــا مــا ذكــره املدعــي العــام واملدعيــة باحلــق اخلــاص فبعضــه‬\n      ‫صحيــح وبعضــه غيــر صحيــح والصحيــح منــه أننــي قلــت لهــا انقلعــي بــرا‬\n      ‫وســوف أشــكيك علــى املديــر هــذا هــو الصحيــح وأمــا غيــر الصحيــح‬\n      ‫فهــو مــا ذكرتــه مــن أننــي قلــت فصلتــك علــى يــدي علمــا أننــي اعتــذرت‬\n      ‫مــن املدعيــة وســامحتني علــى ذلــك هــذه إجابتــي وبعــرض إجابتهــا علــى‬\n      ‫املدعــي العــام واملدعيــة باحلــق اخلــاص قــرر املدعــي العــام بقولــه ‪ :‬إنهــا‬\n\n\n‫‪163‬‬\n\f‫أيضــا تلفظــت بقولهــا فصلتــك علــى يــدي فســألته البينــة علــى ذلــك‬\n‫فقــال بينتــي مــا جــاء يف الالئحــة ومــا ورد يف طيــات املعاملــة هكــذا قــرر‬\n‫كمــا أجابــت املدعيــة باحلــق اخلــاص بقولهــا نعــم ســامحتها حــن كنا يف‬\n‫املســتوصف حــن اعتــذرت منــي وخرجــت ثــم عــاد زوجهــا بعــد ذلــك وهــو‬\n‫مــن تلفــظ هكــذا قــررت والنتهــاء وقــت اجللســة فقــد قــررت رفعهــا ويف‬\n‫جلســة أخــرى حضــر جميــع األطــراف فبعــد ســماع الدعــوى واإلجابــة‬\n‫واالطــاع علــى أوراق املعاملــة ونظــر ًا إلقــرار املدعــى عليــه األول بدعــوى‬\n‫ا ويف هــذا أدانــه‬  ‫املدعــى العــام واملدعيــة باحلــق اخلــاص جملــة وتفصي ـ ً‬\n‫لــه مبــا يدعيانــه وإلقــرار املدعــى عليهــا الثانيــة ‪ ......‬ببعــض مــا جــاء‬\n‫يف دعــوى املدعــى العــام واملدعيــة باحلــق اخلــاص وإقــرار املدعيــة باحلــق‬\n‫اخلــاص بتنازلهــا عــن املدعــى عليهــا الثانيــة ‪ ......‬ونظــر ًا ألن قــول املدعــى‬\n‫عليــه األول محــرم شــرع ًا وســباب ألخيــه املســلم وقــد قــال عليــه الصــاة‬\n‫والســام (ســباب املســلم فســوق وقتالــه كفــر ) كمــا أنــه صلــى اهلل‬\n‫عليــه وســلم قــال (كل املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه)‬\n‫رواه مســلم فــكان يجــب علــى املدعــى عليــه األول عــدم التلفــظ بهــذه‬\n‫األلفــاظ احملرمــة وعــدم االعتــداء علــى أخيــه املســلم وإن كان ثمــة خطا‬\n‫مــن املدعيــة كمــا يدعــي فيتقــدم للجهــة املختصــة بذلــك للشــكاوى‬\n‫كمــا أن يف تلفــظ املدعــى عليهــا الثانيــة إخــال بالنظــام العــام ويف حــق‬\n‫املوظــف العــام وكان األولــى اتبــاع الطــرق النظاميــة يف ذلــك مــن تقــدمي‬\n‫شكاوى رسمية يف أي خطأ يصدر من أي موظف ال أن يتلفظ اإلنسان‬\n‫ويخالــف بذلــك األنظمــة عليــه أوال ‪ :‬رددت دعــوى املدعيــة باحلــق اخلــاص‬\n‫طلبهــا تأديــب املدعــى عليهــا الثانيــة لقــاء مــا تلفظــت بــه عليهــا وذلــك‬\n‫بإقرارهــا بتنازلهــا عنهــا وبذلــك حكمــت باحلــق اخلــاص ثانيــا ثبــت لــدي‬\n\n\n                                                                                         ‫‪164‬‬\n\f      ‫إدانــة املدعــى عليــه األول بتلفظــه علــى املدعيــة باحلــق اخلــاص بقولــه لهــا (‬\n      ‫اهلل يلعــن اللــي ربــاك ) وكان ذلــك أثنــاء تأديتهــا عملهــا وقــررت تعزيــره‬\n      ‫علــى ذلــك بجلــده ثمــان جلــدات مقســمة علــى النصــف للحــق العــام واحلــق‬\n      ‫اخلــاص يبــدأ أوال باحلــق العــام وبأخــذ التعهــد عليــه بعــدم العــودة ملثــل مــا‬\n      ‫بــدر منــه وبذلــك حكمــت ثالثــا ‪ :‬ثبــت لــدي إدانــة املدعــى عليهــا الثانيــة‬\n      ‫بالتلفــظ علــى املدعــى عليهــا باحلــق اخلــاص بقولهــا ( انقلعــي واطلعــي بــرا‬\n      ‫) وبنــاء عليــه فقــد أمــرت للحــق العــام بأخــذ التعهــد عليهــا بعــدم العــودة‬\n      ‫ملثــل مــا بــدر منهــا وبذلــك حكمــت وبعــرض احلكــم علــى األطــراف‬\n      ‫قــرر املدعــى العــام عــدم القناعــة باحلكــم مكتفي ـ ًا بالئحــة الدعــوى‬\n      ‫املقدمــة معتبــر ًا إياهــا الئحــة اعتراضيــة واملدعــى عليهــا باحلــق اخلــاص‬\n      ‫قــررت عــدم القناعــة باحلكــم ورفعهــا بالئحــة اعتراضيــة وأفهمــت‬\n      ‫املدعيــة باحلــق اخلــاص بــأن لهــا ثالثــون يومــا مــن تاريــخ صــدور احلكــم‬\n      ‫يف ‪1434/05/26‬ه ـ وأنهــا إذا لــم تقــدم اعتراضهــا خــال هــذه املــدة فإن‬\n      ‫حقهــا يف تقــدمي الالئحــة يســقط وترفــع املعاملــة حملكمــة االســتئناف‬\n      ‫لتدقيــق احلكــم ففهمــت ذلــك كمــا قــرر املدعــى عليهمــا كل واحــد‬\n      ‫منهمــا مبفــرده قناعتــه باحلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                     ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/25‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بعنيــزة برقــم ‪ 34186693‬وتاريــخ ‪ 1434/04/23‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34992714‬وتاريــخ ‪1434/04/22‬ه ـ ففــي يــوم‬\n      ‫االثنــن املوافــق‪ 1434/08/01‬ه ـ افتتحــت اجللســة الســاعة التاســعة‬\n      ‫وخمســة وأربعــن دقيقــة وفيهــا عــادت املعاملــة مــن محكمــة االســتئناف‬\n\n\n‫‪165‬‬\n\f‫وبرفقها القرار رقم ‪ 34264827‬يف ‪1434/7/10‬هـ الصادر من الدائرة‬\n‫اجلزائيــة األولــى بحكمــة االســتئناف بالقصيــم وقــد صــدق احلكــم‬\n‫باألكثريــة قاضــي اســتئناف ‪ .....‬ختمــه وتوقيعــه قاضــي اســتئناف ‪...‬‬\n‫ختمــه وتوقيعــه ولــه وجهــة نظــر رئيــس الدائــرة ‪...‬ختمــه وتوقيعــه وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                     ‫حــرر يف ‪1434/8/1‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                    ‫‪166‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":159,"source_page_end":166,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b8c33d53438062c786ea28598942c80978dae0520c3e0ec8722e2c57e3da6e2f","normalized_text_hash":"b95931c8396e7005c4b203b25d50163e9a2bb4cfeb9c97a1732b9a84e1e7e5c5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p159-34222635"},{"id":"27bb5e13-ea9c-5584-ac42-c813e29aaaee","document_type":"judgment","category":"judicial","subcategory":"general","title":"سب وشتم -حق عام -إقرار -ثبوت إدانة -تعزير -جلد . القاعدة الفقهية (اإلقرار حجة على املقر وال عذر ملن أقر ) .","document_number":"34314511","case_number":"34395152","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/08/23","year":"1434","subject":"سب وشتم -حق عام -إقرار -ثبوت إدانة -تعزير -جلد . القاعدة الفقهية (اإلقرار حجة على املقر وال عذر ملن أقر ) .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34314511:‬تاريخه‪1434/08/23 :‬هـ‬\n                     ‫رقم الدعوى‪34395152:‬‬\n              ‫رقم قرار التصديق من محكمة‬\n  ‫االستئناف‪ 34344965:‬تاريخه‪1434/10/29:‬هـ‬\n\n\n              ‫سب وشتم ‪ -‬حق عام ‪ -‬إقرار ‪ -‬ثبوت إدانة ‪ -‬تعزير ‪ -‬جلد ‪.‬‬\n\n\n\n\n            ‫القاعدة الفقهية (اإلقرار حجة على املقر وال عذر ملن أقر ) ‪.‬‬\n\n\n\n\n ‫اتهــام املدعــي العــام املدعــى عليــه بقيامــه بسـ ــب شــخص وقذفــه ويطلــب‬\n ‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة ت ـع ــزيرية تزجــره وتــردع‬\n ‫غيــره‪ ،‬حيــث إنــه بتاريــخ ‪1434/5/12‬ه ـ ورد بــاغ ملخفــر شــرطة ‪......‬‬\n ‫يفيــد فيــه املُبلــغ بتعرضــه للتلفــظ مــن قبــل املتهــم املذكــور أعــاه أثنــاء‬\n ‫تأديتــه مهــام عملــه يف صيدليــة مستشــفى ‪ ......‬العــام ‪ ،‬إقــرار املدعــى‬\n ‫عليــه مبــا جــاء يف الدعــوى ‪ ،‬ثبــوت اإلدانــة واحلكــم بجلــده خمــس‬\n ‫عشــرة جلــدة ‪ ،‬قــرر املدعــي العــام االعتــراض وطلب االســتئناف بالئحة‬\n ‫وقــرر املدعــى عليــه القناعــة ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                         ‫‪170‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":170,"source_page_end":170,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3aa94a5a336e311afb99a13b98a4326a03ac20f4059f15c05ba0ed3060627f03","normalized_text_hash":"bfa05cef98fdd48b3f7386a13ec9c146ba770ad2ca9962ae16efa6cc9085e78a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p170-34314511"},{"id":"89441c21-1fa5-5d2c-8fbd-2527ca4f3512","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -شكوى كيدية -مطالبة املدعي بتعزير املدعى عليه -بينة املدعي غير موصلة -رد الدعوى -مين املدعى عليه على نفي الدعوى بعد اكتساب احلكم القطعية.","document_number":"341787359","case_number":"344902","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/3","year":"1434","subject":"إيذاء الغير (حق خاص) -شكوى كيدية -مطالبة املدعي بتعزير املدعى عليه -بينة املدعي غير موصلة -رد الدعوى -مين املدعى عليه على نفي الدعوى بعد اكتساب احلكم القطعية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/3 :‬هـ‬\n                     ‫ُ‬                  ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪341787359 :‬‬\n                           ‫َر ْق ُم الدعوى‪344902 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34247853‬تاريخه‪1434/06/21 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬شــكوى كيديــة‪ -‬مطالبــة املدعــي بتعزيــر‬\n      ‫املدعــى عليــه‪ -‬بينــة املدعــي غيــر موصلــة‪ -‬رد الدعــوى‪ -‬ميــن املدعــى‬\n                  ‫عليــه علــى نفــي الدعــوى بعــد اكتســاب احلكــم القطعيــة‪.‬‬\n\n\n\n      ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                                ‫يف تســبيب حكمــه ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه قــدم ضــده شــكوى كيديــة ملركــز‬\n      ‫الشــرطة فتمــت إحالتــه للتحقيــق علــى إثرهــا ولــم يتمكــن املدعــى‬\n      ‫عليــه مــن تقــدمي مــا يثبــت تلــك الشــكوى‪ ،‬ولــذا فقــد طلــب احلكــم‬\n      ‫عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أقــر املدعــى عليــه بأنــه قــدم شــكوى‬\n      ‫ضــد املدعــي ودفــع بأنهــا ليســت كيديــة لكــون املدعــي خصــم لوالــده‬\n      ‫وبينهمــا خالفــات وقــد هــدد والــده بالقتــل كمــا أقــر بأنــه لــم يســتطع‬\n      ‫إثبــات ذلــك لــدى احملقــق‪ -‬املدعــي لــم يقــدم بينــة موصلــة إلثبــات كيدية‬\n      ‫الشــكوى ولــم يقبــل ميــن خصمــه علــى نفــي دعــواه‪ -‬قضــت احملكمــة‬\n      ‫بصــرف النظــر عــن دعــوى املدعــي لعــدم ثبوتهــا وأفهمتــه بــأن لــه ميــن‬\n      ‫املدعــى عليــه متــى طلبهــا‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه‬\n\n‫‪177‬‬\n\f‫املدعــي‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪ -‬بعــد‬\n‫اكتســاب احلكــم الصفــة القطعيــة طلــب املدعــي ميــن املدعــى عليــه‬\n ‫علــى نفــي دعــواه فأداهــا طبــق مــا طلــب منــه وبذلــك انتهــت الدعــوى‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا ‪ .....‬القاضي يف احملكمة اجلزائية مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة برقــم ‪ 344902‬وتاريــخ ‪ 1434/01/04‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 3421524‬وتاريــخ ‪1434/1/4‬ه ففــي يــوم‬\n‫االثنــن املوافق‪1434/04/01‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬واملدعــى عليــه‬\n‫‪ ....‬ســعودي مبوجــب الســجل املدنــي رقــم ‪ ....‬وادعــى األول قائــا ادعــي‬\n‫علــى هــذا احلاضــر معــي حيــث ان املذكــور قــام بتقــدمي شــكوى‬\n‫لــدى شــرطة التنعيــم بصفتــه وكيــا عــن والــده يتهمنــي بشــكاوي‬\n‫كيديــة وقــد قامــت شــرطة التنعيــم بالتحقيــق معــي ومت حتويــل املعاملــة‬\n‫لهيئــة التحقيــق واالدعــاء العــام اطلــب معاقبــة املدعــى عليــه حيــث ان‬\n‫هــذه الدعــوى التــي قــام بتقدميهــا هــي دعــوى كيديــة وغيــر صحيحــة‬\n‫هكــذا ادعــى املدعــي وبعــرض ذلــك علــى املدعــى عليــه اجــاب قائــا مــا‬\n‫ذكــره املدعــي مــن اتهامــي بتقــدمي دعــوى كيديــة كلــه غيــر صحيــح‬\n‫وانــا قدمــت دعــوى صحيحــة للشــرطة لكــون املدعــي اتصــل بوالــدي‬\n‫وهــدده بالقتــل ولكــن ذلــك لــم يثبــت واحيلــت للشــرطة للحفــظ وبســؤال‬\n‫املدعــي هــل هنــاك خــاف بينكمــا قبــل هــذه الدعــوى فقــال نعــم يوجــد‬\n‫خــاف بينــي وبــن والــد املدعــى عليــه يف قضيــة اخــرى كمــا جــرى‬\n\n                                                                                   ‫‪178‬‬\n\f      ‫ســؤال املدعــى عليــه عــن اخلــاف فقــال نعــم يوجــد خــاف ســابق بــن‬\n      ‫والــدي واملدعــي وبســؤال املدعــي هــل لديــه بينــة علــى ان الدعــوى التــي‬\n      ‫قدمهــا املدعــى عليــه وكالــة دعــوى كيديــة فقــال بينتــي هــو عــدم ثبــوت‬\n      ‫الدعــوى ووجــود احلقــد والكراهيــة بينــي وبــن املدعــى عليــه ووالــده‬\n      ‫وليــس لــدي بينــات غيــر ذلــك ثــم جــرى افهــام املدعــي بــان لــه ميــن املدعى‬\n      ‫عليــه بــان دعــواه التــي تقــدم بهــا لشــرطة التنعيــم هــي دعــوى صحيحــة‬\n      ‫ولــم يكــن غرضــه منهــا الكيــد واالضــرار باملدعــي فقــال املدعــي ال‬\n      ‫اريــد ميــن املدعــى عليــه وال اقبــل ميينــه فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واالجابــة وحيــث لــم يقــدم املدعــي البينــة علــى صحــة دعــواه وقــرر عــدم‬\n      ‫قبــول ميــن املدعــى عليــه لذلــك فقــد صرفــت النظــر عــن دعــوى املدعــي‬\n      ‫وحكمــت بســقوطها لعــدم ثبوتهــا وافهمــت املدعــي بــان لــه ميــن املدعــى‬\n      ‫عليــه متــى طلبهــا وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n      ‫املوافقــة علــى احلكــم كمــا قــرر املدعــي االعتــراض بالئحــة وافهــم‬\n      ‫باحلضــور يــوم االربعــاء املوافــق ‪1434/04/03‬ه ـ الســتالم نســخة مــن‬\n      ‫اعــام احلكــم وان عليــه اعادتــه برفــق الالئحــة خــال مــدة ثالثــن يومــا‬\n      ‫مــن هــذا التاريــخ املــدون اعــاه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                     ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/1‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم االربعــاء املوافــق ‪1434/12/25‬‬\n      ‫ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي واملدعــى عليــه وطلــب املدعــي‬\n      ‫ميــن املدعــى عليــه علــى نفــي دعــواه وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫اســتعد بــأداء اليمــن فحلــف قائــا واهلل العظيــم الــذي ال الــه غيــره ان‬\n      ‫مــا ذكــره هــذا املدعــي مــن انــي تقدمــت ضــده بدعــوى كيديــه فذلــك‬\n      ‫غيــر صحيــح ومــا تقدمــت بــه صحيــح ولــم اقصــد منــه الكيــد واالضــرار‬\n\n\n‫‪179‬‬\n\f‫باملدعــي هكــذا حلــف املدعــى عليــه وبنــاء عليــه فقــد ثبــت لــدي اداء‬\n‫املدعــى عليــه لليمــن بطلــب املدعــي وتعتبــر القضيــة منتهيــه بذلــك‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                          ‫وســلم ‪ .‬حــرر يف ‪1434/12/25‬هــ‪.‬‬\n‫احلمــدهلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبكــة املكرمــة بالقــرار رقــم ‪ 34247853‬يف ‪1434/6/21‬ه ـ‬\n                             ‫ومضمــون القــرار املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n                                                                               ‫‪180‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":177,"source_page_end":180,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"195e6a07e8a8c11c5b02208fdbcf4d2bc1427eb69dab92103b9c58c97578a03f","normalized_text_hash":"acc5bf46a94b6df256d38f75718da8d372bb2944b097ca3a2878f6830158b1f7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p177-341787359"},{"id":"e2e8d426-501d-5e80-b84a-867048e12a3a","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب -مصادقة املدعى عليها على الدعوى -ثبوت الدعوى -إدانة املدعى عليها.","document_number":"34311083","case_number":"3437491","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/2","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب -مصادقة املدعى عليها على الدعوى -ثبوت الدعوى -إدانة املدعى عليها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/9/2 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34311083 :‬‬\n                          ‫َر ْق ُم الدعوى‪3437491 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34379729‬تاريخه‪1434/12/17 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب‪ -‬مصادقــة املدعــى عليهــا‬\n                           ‫علــى الدعــوى‪ -‬ثبــوت الدعــوى‪ -‬إدانــة املدعــى عليهــا‪.‬‬\n\n\n\n\n                         ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعيــة بــأن املدعــى عليهــا قامــت بصفــع موكلتــه بيدهــا‬\n      ‫علــى وجههــا‪ ،‬و طلــب احلكــم عليهــا بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أقــر‬\n      ‫وكيــل املدعــى عليهــا مبــا جــاء يف الدعــوى‪ -‬قضــت احملكمــة بإدانــة‬\n      ‫املدعــى عليهــا مبــا نســب إليهــا وقــررت جلدهــا عشــر جلــدات‪ -‬قنــع‬\n      ‫وكيــل املدعيــة باحلكــم وعــارض عليــه وكيــل املدعــى عليهــا‪ -‬قــررت‬\n                                   ‫محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمد هلل وحده وبعد فلدي أنا ‪ ....‬القاضي يف احملكمة اجلزائية مبكة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة مبكــة املكرمــة برقــم ‪ 3437491‬وتاريــخ ‪1434/01/21‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34183652‬وتاريــخ ‪1434/1/21‬ه ففــي يــوم‬\n‫‪181‬‬\n\f‫االثنــن املوافق‪1434/05/13‬ه ـ افتتحــت اجللســة الســاعة ‪ 02 :30‬وفيها‬\n‫حضر‪ /‬سعودي اجلنسية بالسجل املدني رقم ( ) الوكيل الشرعي عن‪/‬‬\n‫مبوجــب الوكالــة الشــرعية رقــم ‪ 34134154‬يف ‪1434/2/4‬ه املخولــة‬\n‫لــه حــق اإلقــرار واإلنــكار والصلــح وادعــى قائــا يف دعــواه ضــد‪ /‬أن‬\n‫موكلتــي ذهبــت لعــزاء خالتهــا وأثنــاء وجودهــا يف العــزاء قامــت املدعــى‬\n‫عليهــا بصفعهــا كف ـ ًا أطلــب تعزيرهــا علــى ذلــك هــذه دعــواي وبعــرض‬\n‫ذلــك علــى وكيــل املدعــى عليهــا احلاضــر‪ /‬ســعودي اجلنســية بالســجل‬\n‫املدنــي رقــم ( ) بالوكالــة الشــرعية رقــم ‪ .....‬يف ‪1434/2/3‬ه ـ املخولــة‬\n‫لــه حــق اإلقــرار واإلنــكار والصلــح صــادق علــى الدعــوى وقــال حاولنــا‬\n‫الصلــح بعــوض فرفضــت هكــذا أجــاب ومبحاولــة الصلــح بــن الطرفــن‬\n‫رفضــا ذلــك وعليــه وبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة وبنــاء على‬\n‫مصادقــة وكيــل املدعــى عليهــا علــى الدعــوى وحلرمــة مــا اقدمــت عليــه‬\n‫املدعــى عليهــا لــذا فقــد حكمــت علــى املدعــى عليهــا بــأن جتلــد عشــرة‬\n‫اســواط دفعــة واحــدة تعزيــرا بحضــور املدعيــة وبعرضــه عليهمــا قنــع بــه‬\n‫املدعــي وطلــب وكيــل املدعــى عليهــا االعتــراض بالئحــة فأفهمتــه أن‬\n‫يتقــدم بهــا خــال ثالثــن يومــا مــن تاريــخ اســتالمه صــورة مــن احلكــم‬\n‫واال اكتســب احلكــم القطعيــة وبــاهلل تعالــى التوفيــق وصلــى اهلل علــى‬\n        ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/05/13‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبكــة املكرمــة بالقــرار رقــم ‪ 34379729‬يف ‪ 1434/12/17‬ه ـ‬\n‫ومضمونــه املصادقــة علــى احلكــم وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                 ‫وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                      ‫‪182‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":181,"source_page_end":182,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"554e5f7c7ddb49485fb33d02d28b0c06536f78171133307785f59652e77d89cb","normalized_text_hash":"bbd6c0d121cbc07d5ef59aac4344058a2d440364bce6b8ffce9213ec688da691","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p181-34311083"},{"id":"46ca74d3-5d8e-53aa-8664-566b26fc7c01","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتسبب يف إصابة - مطالبة املدعي باملجازاة -إقرار املدعى عليه بالدعوى -عدم قبول دفع الدفاع عن النفس -إدانة املدعى عليه.","document_number":"34274834","case_number":"3449576","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم بعد اإلجراء األخير","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/22","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتسبب يف إصابة - مطالبة املدعي باملجازاة -إقرار املدعى عليه بالدعوى -عدم قبول دفع الدفاع عن النفس -إدانة املدعى عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/22 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34274834 :‬‬\n                          ‫َر ْق ُم الدعوى‪3449576 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34298513‬تاريخه‪1434/8/16 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب وتســبب يف إصابــة ‪-‬‬\n      ‫مطالبــة املدعــي باملجــازاة ‪ -‬إقــرار املدعــى عليــه بالدعــوى‪ -‬عــدم قبــول‬\n                            ‫دفــع الدفــاع عــن النفــس ‪ -‬إدانــة املدعــى عليــه‪.‬‬\n\n\n\n\n                                                  ‫‪ -1‬الواجب دفع املعتدي باألسهل‪.‬‬\n                                        ‫‪ -2‬املادة (‪ )17‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعــي بــأن املدعــى عليــه قــام باالعتــداء علــى موكلــه‬\n      ‫وذلــك بضربــه بآلــة حــادة علــى رأســه (مفتــاح معدنــي) ممــا تســبب يف‬\n      ‫إصابتــه بجــرح قطعــي ســطحي يف رأســه‪ ،‬وطلــب احلكــم عليــه بعقوبــة‬\n      ‫تعزيريــة لقــاء ذلــك‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى ودفــع بأنــه‬\n      ‫فعــل ذلــك بعــد قيــام املدعــي بخنقــه علــى إثــر خــاف بينهمــا‪ -‬مــا دفــع‬\n      ‫بــه املدعــى عليــه غيــر مقبــول ألن الواجــب دفــع املعتــدي باألســهل‪-‬‬\n      ‫املدعــى عليــه تســبب يف إصابــة املدعــي بجــرح قطعــي ســطحي بفــروة‬\n      ‫الــرأس مــع ســحجات ومــدة شــفاءه املتوقعــة ثالثــة أيــام حســب التقريــر‬\n      ‫الطبــي‪ -‬قضــت احملكمــة بإدانــة املدعــى عليــه مبــا نســب إليــه وقــررت‬\n      ‫ســجنه ملــدة خمســة أيــام وجلــده خمــس عشــرة جلــدة دفعــة واحــدة‪ -‬قنــع‬\n\n‫‪183‬‬\n\f‫وكيــل املدعــي باحلكــم وعــارض عليــه املدعــى عليــه‪ -‬قــررت محكمــة‬\n          ‫االســتئناف املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪.‬‬\n\n\n\n\n‫فلدي أنا‬\n      ‫َّ‬     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n‫ـاء علــى املعاملــة املقيــدة‬\n                           ‫(‪ ).....‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫بهــذه احملكمــة برقــم ‪ 34244695‬وتاريــخ ‪1434/01/27‬ه ـ واحملالــة‬\n‫إلينــا مــن فضيلــة الرئيــس برقــم ‪ 3449576‬وتاريــخ ‪1434/01/27‬ه ـ ـ‬\n‫فتحــت اجللســة وفيهــا حضــر املدعــي‪ ).....( /‬ســعودي بالســجل املدنــي‬\n‫(‪ ).....‬الوكيــل الشــرعي عــن بالوكالــة رقــم ‪ 3428020‬تاريــخ‬\n‫‪1434/01/07‬ه ـ الصــادرة مــن كتابــة العــدل الثانيــة مبكــة املكرمــة‬\n‫ووكالتــه تخولــه املرافعــة واإلقــرار واإلنــكار والصلــح وا َّدعــى علــى‬\n‫ا‬‫احلاضــر معــه ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم قائ ـ ً‬\n‫إن املدعــى عليــه قــام بضــرب موكلــي علــى رأســه مبفــك‬          ‫يف دعــواه‪َّ :‬‬\n‫(ســكروب) مما أ َّدى إلى إصابته بجرح قطعي يف رأســه أطلب احلكم‬\n‫علــى املدعــى عليــه بإثبــات إدانتــه بذلــك وتعزيــره هــذه دعــواي وبعــرض‬\n‫دعــوى املدعــي وكالــة علــى املدعــى عليــه قــال‪ :‬مــا ذكــره املدعــي‬\n‫وكالــة يف دعــواه فصحيــح فقــد ضربتــه باملفــك علــى رأســه بســبب‬\n‫خــاف بيننــا وذلــك أنــه يتصــل بوالدتــي ويخبرهــا بأمــوري اخلاصــة وقــد‬\n‫حصــل نــزاع بيننــا يف الســيارة وقــام بخنقــي فقمــت بضربــه علــى رأســه‬\n‫باملفــك وقــد حاولــت الصلــح معهــم لكنهــم رفضــوا الصلــح هكــذا‬\n‫أجــاب ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة ومنهــا‪ :‬التقريــر‬\n‫الطبــي الصــادر مــن مستشــفى اجلفــر العــام برقــم ‪41/26/15/3/3793‬‬\n\n                                                                                      ‫‪184‬‬\n\f      ‫وتاريــخ ‪1433/12/20‬ه ـ املتضمــن إصابــة املدعــي أصالــة بجــرح‬\n      ‫قطعــي ســطحي بفــروة الــرأس مــن اليمــن حوالي(‪7‬ســم) وآخــر مــن‬\n      ‫اليســار طولــه حوالــي (‪5‬ســم) مــع ســحجة بالســاعد األميــن وســحجة‬\n      ‫مت عمــل الــازم لــه ومــدة الشــفاء ثالثــة أيــام مالــم‬\n                                                                ‫بالســاعد األيســر و َّ‬\n      ‫حتــدث مضاعفــات‪ .‬أ‪.‬ه ـ وبعرضــه علــى املدعــى عليــه قــال‪ :‬ال أعلــم‬\n      ‫عمــا أصــاب املدعــي هكــذا قرركمــا حضــر يف اجللســة املدعــي العــام‬             ‫َّ‬\n      ‫امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطــاب ســعادة رئيــس‬\n      ‫دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء ذي الرقــم ‪13415‬‬\n      ‫والتاريــخ ‪1433/12/1‬ه ـ وجــرى ســؤاله هــل لــه دعــوى يف هــذه القضيــة‬\n      ‫اســتناد ًا إلــى املــادة الســابعة عشــرة مــن نظــام اإلجــراءات اجلزائيــة فقــال‪:‬‬\n      ‫أي مطالبــة‬ ‫إن مرجعــي لــم يخولنــي باملطالبــة يف هــذه الدعــوى وليــس لــي ُّ‬          ‫َّ‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا‬\n                                                         ‫حاليــا هكــذا أجــاب فبنـ ً‬  ‫ًّ‬\n      ‫أن املدعــى عليــه أقـ َّـر بدعــوى املدعــي وكالــة وأنــه هــو قــام بطعــن‬           ‫َّ‬\n      ‫املدعــي أصالــة مبفــك علــى رأســه ودفــع بأ َّنــه كان يدافــع عــن نفســه‬\n      ‫أن مــا دفــع بــه غيــر مقبــول إذ كان الواجــب أن يدفــع باألســهل لــذا‬    ‫ومبــا َّ‬\n      ‫ـدي إدانــة املدعــى عليــه بطعــن املدعــي أصالــة (‪ ).....‬يف‬\n                                                                   ‫كلــه فقــد ثبــت لـ َّ‬\n      ‫رأســه مبفــك وإصابتــه باإلصابــات املذكــورة يف التقريــر الطبــي أعــاه‬\n      ‫وعزرتــه لقــاء ذلــك بســجنه ملــدة خمســة أيــام حتتســب منهــا املــدة التــي‬\n      ‫أوقــف فيهــا علــى ذمــة القضيــة إن وجــدت وبجلــده خمــس عشــرة جلــدة‬\n      ‫دفعــة واحــدة بحضــور املدعــي أصالــة وبذلــك حكمــت وبعــرض احلكــم‬\n      ‫علــى الطرفــن قــرر املدعــي وكالــة القناعــة بــه وقــرر املدعــى عليــه عــدم‬\n      ‫القناعــة بــه وطلــب رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n      ‫لتدقيــق احلكــم دون الئحــة اعتراضيــة وصلــى اهلل وس ـلَّم علــى نبينــا‬\n\n\n‫‪185‬‬\n\f          ‫محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/07/22‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي يوم‬\n              ‫اخلميــس ‪1434/10/15‬ه ـ فتحــت اجللســة الثالثــة وقــد عـ ْ‬\n‫ـادت املعاملــة‬\n‫املتعلقــة بالدعــوى املقامــة مــن مــن محكمــة االســتئناف باملنطقــة‬\n‫الشــرقية مبوجــب خطــاب فضيلــة رئيســها ذي الرقــم ‪34/1892793‬‬\n‫وتاريــخ ‪1434/9/10‬ه ـ وبرفقهــا قــرار الدائــرة اجلزائيــة الثانيــة رقــم‬\n‫(‪34298513‬ج‪ )2/‬وتاريــخ ‪1434/08/16‬ه ـ املتضمــن مــا نصــه‪:‬‬\n‫«وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن ماحكــم‬\n‫بــه فضيلتــه علــى املدعــى عليــه مــن جــزاء قليــل لوجــود إصابــات باملجنــي‬\n‫عليــه ملالحظــة مــا ذكــر وإكمــال مــا يلــزم ومــن ثــم إعــادة املعاملــة‬\n‫إلكمــال الزمهــا واهلل املوفق»‪.‬أ‪.‬ه ـ عليــه ُأ ِجيـ ُـب أصحــاب الفضيلــة‬\n‫ـأن القضيــة حــق خــاص وليســت دعــوى عامــة‬       ‫نفعنــي اهلل بتوجيههــم‪ :‬بـ َّ‬\n‫وقــد قنــع املدعــي وكالــة باحلكــم وهــو صاحــب احلــق وقــد جــرى عــرض‬\n‫احلكــم عليــه مــرة أخــرى فقــال‪ :‬إننــي قانــع مبــا ورد يف احلكــم وال أريــد‬\n‫زيــادة عليــه هكــذا أجــاب وعليــه فلــم يظهــر لــي ســوى مــا حكمــت‬\n‫ـرت بالتهميــش علــى الصــك مبــا طــرأ علــى ضبطــه ومــن‬      ‫بــه ســابق ًا وأمـ ُ‬\n‫ثــم بعــث كامــل أوراق املعاملــة حملكمــة االســتئناف باملنطقــة الشــرقية‬\n‫لتدقيــق احلكــم وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                          ‫أجمعــن حــرر يف ‪1434/10/15‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ج‪ 34/2475439/2/‬وتاريــخ ‪1434/10/25‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء‬\n\n\n                                                                                        ‫‪186‬‬\n\f      ‫املكلــف برقــم ‪ 341892793‬وتاريــخ ‪1434/10/25‬ه املرفــق بهــا‬\n      ‫القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ).....(/‬املســجل‬\n      ‫برقــم ‪ 34274834‬وتاريــخ ‪1434/7/22‬ه اخلــاص بدعــوى‪ ).....(/‬ضــد‪/‬‬\n      ‫(‪ ).....‬يف قضيــة مضاربــة وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو‬\n      ‫مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫وباإلطــاع علــى مــا أجــاب بــه فضيلتــه علــى قرارنــا رقــم ‪/34298513‬‬\n      ‫ج‪/2‬ب وتاريــخ ‪1434/8/16‬ه قررنــا املصادقــة علــى احلكم بعد اإلجراء‬\n      ‫األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n                                                       ‫حــرر يف ‪1434/11/26‬هــ‪.‬‬\n\n\n\n\n‫‪187‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":183,"source_page_end":187,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"069913927460f0e4139ac17a156e2aa33b50592e54e8438d027c3b65d19bc8ff","normalized_text_hash":"d347bb1606be0bb2cdd7f73220898edbaa1d3b7d17065e0be7c761615c4645c7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p183-34274834"},{"id":"ec885d92-bfb1-5f56-a796-97efac7f211a","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -إساءة استعمال السلطة -مطالبة املدعي بالتعزير -حصر املدعي دعواه يف طلب محاسبة املدعى عليهم لتجاوزهم النظام أثناء تأدية عملهم الوظيفي وإحلاقهم الضرر به -عدم اختصاص والئي -رد الدعوى.","document_number":"34408552","case_number":"3480956","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/10","year":"1434","subject":"إيذاء الغير (حق خاص) -إساءة استعمال السلطة -مطالبة املدعي بالتعزير -حصر املدعي دعواه يف طلب محاسبة املدعى عليهم لتجاوزهم النظام أثناء تأدية عملهم الوظيفي وإحلاقهم الضرر به -عدم اختصاص والئي -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/10 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34408552 :‬‬\n                    ‫َر ْق ُم الدعوى‪3480956 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34193419‬تاريخه‪1434/4/21:‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬إســاءة اســتعمال الســلطة‪ -‬مطالبــة املدعــي‬\n‫بالتعزيــر‪ -‬حصــر املدعــي دعــواه يف طلــب محاســبة املدعــى عليهــم‬\n‫لتجاوزهــم النظــام أثنــاء تأديــة عملهــم الوظيفــي وإحلاقهــم الضــرر‬\n                             ‫بــه‪ -‬عــدم اختصــاص والئــي‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n‫‪ -1‬املــواد (‪ )11‬و(‪ )15‬مــن نظــام اخلدمــة املدنيــة الصــادر باملرســوم امللكي‬\n                                             ‫رقــم م‪ 9/‬وتاريخ ‪1397/7/10‬هـ‪.‬‬\n                           ‫‪ -2‬املادة (‪ )128‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بــأن املدعــى عليهــم قامــوا باســتغالل الســلطة املمنوحــة‬\n‫لهــم يف جهــة العمــل التــي يعملــون بهــا وذلــك بكتابــة خطــاب إلــى الوزيــر‬\n‫املختــص يتضمــن معلومــات مخالفــة لنتيجــة التحقيــق التــي أجروهــا مــع‬\n‫املدعــي يف شــكوى مقدمــة ضــده مــن بعــض زمالئــه يف العمــل ولــذا‬\n‫فقــد طلــب احلكــم عليهــم بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى‬\n‫عليــه األول مــا جــاء يف دعــوى املدعــي ودفــع بعــدم االختصــاص‪ -‬املدعــي‬\n‫حصــر دعــواه يف طلــب محاســبة املدعــى عليهــم لتجاوزهــم النظــام‬\n‫أثنــاء تأديــة عملهــم الوظيفــي وإحلاقهــم الضــرر بــه مبــا تضمنــه اخلطــاب‬\n\n                                                                                     ‫‪196‬‬\n\f      ‫املذكــور وذلــك شــأن إداري محكــوم بنظــام املوظفــن العــام ونظــام‬\n      ‫تأديبهــم‪ -‬قضــت احملكمــة بصــرف النظــر عــن دعــوى املدعــي لعــدم‬\n      ‫االختصــاص‪ -‬قنــع املدعــى عليــه األول باحلكــم وعــارض عليــه املدعــي‪-‬‬\n                          ‫قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪3480956‬‬\n      ‫وتاريــخ ‪1434/02/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34408552‬وتاريــخ‬\n      ‫‪1434/02/18‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1434/03/02‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 09 : 00‬وفيها ســعودي اجلنســية مبوجب الســجل املدني‬\n      ‫رقــم وقــال إننــي ادعــى علــى كل مــن ‪ /‬وعلــى ‪ /‬ســعودي اجلنســية وعلــى‬\n      ‫‪ /‬ســعودي اجلنســية حيــث أنهــم كتبــوا خطابـ ًا إلــى معالــي وزيــر املاليــة‬\n      ‫ونــص املــراد منــه (( إشــارة إلــى البرقيــة املرفوعــة ملعاليكــم برقــم‬\n      ‫‪ 120703169173‬يف ‪1433/08/18‬ه ـ مــن املوظــف بفــرع املصلحــة‬\n      ‫بجــدة ‪ /‬املتضمنــة قيــام املوظــف بالفــرع ‪ /‬بالتلفــظ عليــه وعلــى زميلــه‬\n      ‫بألفــاظ بذيئــة بالفصــل مــن وظائفهــم بحكــم عالقتــه مبعاليكــم‬\n      ‫وطلــب معاليكــم اإلفــادة ‪ .‬فعليــه أوضــح ملعاليكــم االتــي ‪ -1:‬نظــر ًا‬\n      ‫لعــدم تواجــد بعــض أصحــاب الشــكوى والشــهود علــى رأس العمــل‬\n      ‫عنــد ورود الشــكوى فقــد مت إرجــاء التحقيــق إلــى حــن مباشــرتهم‬\n      ‫ومخاطبــة ســعادة مديــر عــام مكتــب معاليكــم برقــم ‪ 3/1/23‬يف‬\n      ‫‪1433/08/27‬ه ـ بهــذا اخلصــوص ‪ -2 .‬مت تشــكيل جلنــة للتحقيــق‬\n\n‫‪197‬‬\n\f‫يف الشــكوى وقيــام أعضــاء اللجنــة بإجــراء التحقيــق يف املوضــوع‬\n‫مــع األطــراف ذات العالقــة وســماع أقــوال الشــهود وتدوينهــا وإعــداد‬\n‫محضــر بذلــك مــن خاللــه تبــن للجنــة إدانــة املذكــور مبــا نســب إليــه‬\n‫يف الشــكوى املرفوعــة ملعاليكــم باســتثناء أن لــه عالقــة مبعاليكــم‬\n‫إلنــكاره ذلــك وادعائــه أنــه كان يقصــد بالوزيــر ســمو وزيــر الداخليــة‬\n‫ولعــدم كفايــة األدلــة وعــدم اتفــاق الشــهود علــى ذلــك وحيــث كانــت‬\n‫إجابــات املذكــور تفتقــر إلــى التركيــز وظهــر أنــه يعانــي مــن التشــتت‬\n‫يف املوضوعــات وتناقــض مــا ذكــره إضافــة إلــى ســيرته الوظيفيــة‬\n‫عندمــا كان يعمــل بــاإلدارة العامــة ترجــح صحــة مــا جــاء يف الشــكوى‬\n‫ضــده ومــا نســب إليــه ‪ .‬فإننــي أرى والــرأي ملعاليكــم بــأن تقــوم املصلحــة‬\n‫بتوجيــه انــذار شــديد اللهجــة للموظــف ‪ .....‬بــأن عليــه التحلــي باألخــاق‬\n‫الفاضلــة وأن يحســن التعامــل مــع زمالئــه وأن يتجنــب االلفــاظ اجلارحــة‬\n‫وغيــر الالئقــة واالدعــاء بعالقتــه بكبــار املســؤولني ويف حالــة تكــرار‬\n‫مــا حــدث ســوف يكــون عرضــة لعقوبــة أشــد مــع نقلــه لفــرع املصلحــة‬\n‫مبكــة املكرمــة ملصلحــة العمــل وإبعــاده عــن االحتــكاك بزمالئــه‬\n‫الذيــن احتــك معهــم)) والــذي كان بخصــوص نتيجــة التحقيــق يف‬\n‫االدعــاء الغيــر صحيــح واملفتــري مــن املوظــف ‪ .....‬واملوظــف ‪ ،‬والــذي‬\n‫قامــوا فيــه باالفتــراء علـ ّـي وعــدم ذكــر احلقيقــة الكاملــة التــي نتجــت‬\n‫ا قبــل أن‬‫مــن التحقيــق حيــث أنــي أطلعــت علــى محضــر التحقيــق كامـ ً‬\n‫أوقــع عليــه وقــد مت تزويــر احلقيقــة وذلــك اســتغالل الســلطة وتكلفــي‬\n‫بالعمــل مبكــة املكرمــة وهــذا اإلجــراء غيــر نظامــي وعلــى ذلــك أمــل‬\n‫مــن فضيلتكــم ســؤالهم عــن ســبب االفتــراء علـ ّـي ومجازاتهــم شــرع ًا‬\n‫هــذه دعواي‪.‬أ‪.‬ه ـ وبعــرض الدعــوى علــى املدعــى عليــه احلاضــر ‪/‬‬\n\n\n                                                                                    ‫‪198‬‬\n\f      ‫ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم قــال‪ :‬مــا ذكــره املدعــي‬\n      ‫غيــر صحيــح وأنــا أدفــع بعــدم اختصــاص احملكمــة بذلــك حيــث إننــي‬\n      ‫أعمــل مديــر عــام إدارة شــؤون املوظفــن ب ـ ‪ ......‬وأمــا املدعــى عليهمــا‬\n      ‫اآلخــران يعمــل االول يعمــل مديــر عــام ‪ ......‬والثانــي فيعمــل مديــر عــام‬\n      ‫‪ ......‬احلاضــر عنهمــا بالتفويــض الصــادر مــن ‪ ......‬رقــم ‪ 14/9880‬يف‬\n      ‫‪1434/02/27‬ه ـ ثــم ســألت املدعــي هــل دعــواك تنحصــر يف محاســبة‬\n      ‫املدعــى عليهــم عــن اخلطــاب املوجــه لوزيــر املاليــة فقــال نعــم وبعــد التأمــل‬\n      ‫وباالطــاع علــى أوراق املعاملــة و حيــث إن نظــام اخلدمــة املدنيــة الصــادر‬\n      ‫باملرســوم امللكــي رقــم م‪ 9/‬وتاريــخ ‪1397/7/10‬ه ـ النافــذ حالي ـ ًا يف‬\n      ‫اململكــة والــذي تقضــي أحكامــه بصفتــه القاعــدة العامــة بــأن يخضــع‬\n      ‫للمســاءلة التأديبيــة كل مــن يخــرج مــن املوظفــن علــى مقتضــى الواجــب‬\n      ‫يف أداء وظيفتــه أو يظهــر مبظهــر مــن شــأنه اإلخــال بكرامــة وشــرف‬\n      ‫الوظيفــة العامــة (املادة‪11‬مــن نظــام اخلدمــة املدنيــة) كمــا يضيــف‬\n      ‫النظــام بــأن كل موظــف مســئول عمــا يصــدر عنــه ومســؤول عــن حســن‬\n      ‫ســير العمــل يف حــدود اختصاصــه (املــادة ‪ )15‬وحيــث إن دعــوى املدعــي‬\n      ‫قائمــة علــى اتهــام املدعــى عليهــم بتجاوزهــم للنظــام أثنــاء تأديــة عملهــم‬\n      ‫ـاء علــى محضــر خطــاب‬     ‫الوظيفــي واتهماهــم بإحلــاق الضــرر باملدعــي بنـ ً‬\n      ‫موجــه منهــم ملعالــي وزيــر املاليــة مبقتضــي عملهــم الوظيفــي وحيــث إن‬\n      ‫محاســبة املوظــف علــى أدائــه الوظيفــي وجتــاوزه وتفريطــه ومــا يتعلــق بــه‬\n      ‫شــأن إداري محكــوم بأنظمــة املوظفــن العــام ونظــام تأديبهــم وحيــث‬\n      ‫إن املــادة ‪128‬مــن نظــام اإلجــراءات اجلزائيــة تنــص علــى اختصــاص هــذه‬\n      ‫ـاء‬\n      ‫احملكمــة بالنظــر يف العقوبــات التعزيريــة إال مــا يســتثنى بنظــام وبنـ ً‬\n      ‫علــى مــا تقــدم فقــد حكمــت بصــرف النظــر عــن دعــوى املدعــي لعــدم‬\n\n\n‫‪199‬‬\n\f‫االختصــاص النوعــي وبعــرض احلكــم علــى الطرفــن قــرر املدعــي عــدم‬\n‫القناعــة وافهــم بتعليماتــه بــان مــدة االعتــراض ثالثــون يوم ـ ًا مــن تاريــخ‬\n‫تســجيل القــرار ويف حــال لــم يقــدم اعتراضــه ســقط حــق يف االعتــراض‬\n‫واكتســب احلكــم القطعيــة وقــرر املدعــى عليــه األول القناعــة باحلكــم‬\n‫واملدعــى عليهمــا الثانــي والثالــث لــم يحضــرا وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر ‪1434/03/02‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة اجلزائيــة مبحافظة‬\n‫جــدة ففــي يــوم االثنــن املوافــق ‪1434/06/05‬ه ـ افتتحــت اجللســة ولقــد‬\n‫عــادت إلينــا املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة برقــم‬\n‫‪ 34408552‬وتاريــخ ‪1434/04/24‬ه ـ الصــادر فيهــا قــرار التصديــق ذو‬\n‫الرقــم ‪ 34193419‬وتاريــخ ‪1434/04/21‬ه ـ املتضمــن انــه وبدراســة‬\n‫الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر املوافقــة علــى‬\n‫احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                               ‫‪1434/06/05‬هــ‪.‬‬\n\n\n\n\n                                                                                      ‫‪200‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":196,"source_page_end":200,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6e747922e0fde038a24ea79714454bbb1b5ff6078a6c291946d1d1a071d8ae2a","normalized_text_hash":"808672ba26cc8c2fa186968aade5ec15a24a3f4d11f2e6f2b1f8f26a90393321","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p196-34408552"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

